import { test, expect } from '@playwright/test';

test.describe('Error Message Screen Reader Announcement', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/form');
  });

  test('should announce error messages to screen readers when form validation fails', async ({ page }) => {
    // Intercept the API call to simulate error response
    await page.route('**/api/validate', (route) => {
      route.abort('failed');
    });

    // Fill in invalid email
    const emailInput = page.getByLabel('Email Address');
    await emailInput.fill('invalid-email');

    // Submit the form
    const submitButton = page.getByRole('button', { name: /submit/i });
    await submitButton.click();

    // Wait for error message to appear
    await page.waitForTimeout(500);

    // Verify error message is visible
    const errorMessage = page.getByText('Please enter a valid email address');
    await expect(errorMessage).toBeVisible();

    // Verify error message has aria-live region
    const liveRegion = page.locator('[aria-live]');
    await expect(liveRegion).toBeVisible();

    // Verify error message has role="alert"
    const errorElement = page.locator('[data-testid="error-message"]');
    await expect(errorElement).toHaveAttribute('role', 'alert');

    // Verify error message is announced by screen reader
    const announcement = page.getByText('Please enter a valid email address');
    await expect(announcement).toBeVisible();
  });

  test('should announce error messages when multiple fields fail validation', async ({ page }) => {
    // Intercept the API call to simulate multiple errors
    await page.route('**/api/validate', (route) => {
      route.continue();
    });

    // Fill in invalid email
    const emailInput = page.getByLabel('Email Address');
    await emailInput.fill('invalid-email');

    // Fill in invalid password
    const passwordInput = page.getByLabel('Password');
    await passwordInput.fill('short');

    // Submit the form
    const submitButton = page.getByRole('button', { name: /submit/i });
    await submitButton.click();

    // Wait for error messages to appear
    await page.waitForTimeout(500);

    // Verify both error messages are visible
    const emailError = page.getByText('Please enter a valid email address');
    await expect(emailError).toBeVisible();

    const passwordError = page.getByText('Password must be at least 8 characters');
    await expect(passwordError).toBeVisible();

    // Verify error messages are in aria-live regions
    const liveRegion = page.locator('[aria-live]');
    await expect(liveRegion).toBeVisible();

    // Verify error messages have role="alert"
    const errorElements = page.locator('[data-testid="error-message"]');
    await expect(errorElements).toHaveCount(2);
    for (let i = 0; i < 2; i++) {
      const error = errorElements.nth(i);
      await expect(error).toHaveAttribute('role', 'alert');
    }
  });
});
